import com.nigson.shared.problem.*;

/** Capture current owned inputs, release locks, read the provider, then revalidate before binding the fee. */
public final class DeliveryQuoteService {
 private final JdbcTemplate jdbc;private final PricingAuthority authority;private final PricingProviders providers;private final MarketEligibility markets;private final FulfillmentPolicy fulfillment;private final CarrierRates rates;private final ActorDelegation delegation;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final TransactionTemplate snapshots;private final CarrierPacking.Address origin;private final String mode;
 private record Snapshot(UUID cart,UUID market,UUID organization,long version,CarrierPacking.Address address,List<CarrierPacking.Parcel> packages,String addressHash,String packageHash,Instant approvalUntil){@Override public String toString(){return "DeliveryQuoteSnapshot[protected]";}}
 public DeliveryQuoteService(JdbcTemplate jdbc,PlatformTransactionManager manager,PricingAuthority authority,PricingProviders providers,MarketEligibility markets,FulfillmentPolicy fulfillment,CarrierRates rates,ActorDelegation delegation,PlatformStore commands,AuditWriter audit,Clock clock,CarrierPacking.Address origin,String mode){
  if(origin==null||mode==null||!Set.of("MOCK","SANDBOX","LIVE").contains(mode))throw new IllegalArgumentException("CARRIER_ORIGIN_MODE_REQUIRED");this.jdbc=jdbc;this.authority=authority;this.providers=providers;this.markets=markets;this.fulfillment=fulfillment;this.rates=rates;this.delegation=delegation;this.commands=commands;this.audit=audit;this.clock=clock;this.origin=origin;this.mode=mode;snapshots=new TransactionTemplate(manager);snapshots.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);snapshots.setTimeout(5);
 }
 private Snapshot snapshot(ActorAssertion.Actor actor,UUID id,long expected,DeliveryQuoteValues.Input input,boolean lock){
  jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");if(lock)authority.stabilize(actor,"CUSTOMER");else authority.require(actor,"CUSTOMER");
  var carts=jdbc.queryForList("SELECT c.version,c.status,c.market_id,c.organization_id,m.code,m.currency_code FROM commerce.cart c JOIN commerce.market m ON m.id=c.market_id WHERE c.id=? AND c.party_id=?"+(lock?" FOR UPDATE OF c":""),id,actor.party());if(carts.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var cart=carts.getFirst();long version=((Number)cart.get("version")).longValue();if(version!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!"ACTIVE".equals(cart.get("status")))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(!"NG".equals(cart.get("code"))||!"NGN".equals(cart.get("currency_code")))throw FulfillmentValues.rule();UUID organization=(UUID)cart.get("organization_id"),market=(UUID)cart.get("market_id");if(organization!=null)authority.organization(actor,organization,lock);
  var addresses=jdbc.query("SELECT recipient,phone,line1,line2,city,region,postal_code,country_code,organization_id FROM commerce.address WHERE id=? AND party_id=? AND deleted_at IS NULL"+(lock?" FOR SHARE":""),(r,n)->new Object[]{new CarrierPacking.Address(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8)),r.getObject(9,UUID.class)},input.addressId(),actor.party());if(addresses.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var address=(CarrierPacking.Address)addresses.getFirst()[0];if(addresses.getFirst()[1]!=null&&!addresses.getFirst()[1].equals(organization))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);
  var products=new HashSet<UUID>();var items=jdbc.query("SELECT s.id,s.product_id,l.quantity,s.quantity_scale,s.carrier_packaging::text FROM commerce.cart_line l JOIN commerce.sku s ON s.id=l.sku_id JOIN commerce.product p ON p.id=s.product_id WHERE l.cart_id=? AND s.active AND s.deleted_at IS NULL AND p.status='ACTIVE' AND p.deleted_at IS NULL ORDER BY p.id,s.id LIMIT 101"+(lock?" FOR SHARE OF p,s":""),(r,n)->{products.add(r.getObject(2,UUID.class));return new CarrierPacking.Item(r.getObject(1,UUID.class),r.getBigDecimal(3),r.getInt(4),r.getString(5)==null?null:EventCodec.JSON.readTree(r.getString(5)));},id);if(items.isEmpty()||items.size()>100||jdbc.queryForObject("SELECT count(*) FROM commerce.cart_line WHERE cart_id=?",Long.class,id)!=items.size())throw FulfillmentValues.rule();var parcels=CarrierPacking.pack(items);var proof=providers.require(mode);Instant carrierUntil=fulfillment.qualifiedUntil(mode);var addressNode=(tools.jackson.databind.node.ObjectNode)EventCodec.JSON.valueToTree(address);addressNode.put("label","Delivery snapshot");addressNode.put("isDefault",false);markets.require(market,"NG",products,addressNode,proof);
  return new Snapshot(id,market,organization,version,address,parcels,CarrierPacking.hash(address),CarrierPacking.hash(parcels),proof.validUntil().isBefore(carrierUntil)?proof.validUntil():carrierUntil);
 }
 private DeliveryQuoteValues.Quote existing(Snapshot snapshot,String service,boolean lock){var rows=jdbc.query("SELECT id,service_code,delivery_amount,expires_at FROM commerce.carrier_quote WHERE cart_id=? AND cart_version=? AND address_hash=? AND package_hash=? AND service_code=? AND mode=? AND status='QUOTED' AND source_quote_revision_id IS NULL AND expires_at>?"+(lock?" FOR UPDATE":""),(r,n)->new DeliveryQuoteValues.Quote(r.getObject(1,UUID.class),"FEDEX",r.getString(2),"NGN",PricingValues.minor(PricingValues.decimal(r.getBigDecimal(3)),2).toPlainString(),r.getTimestamp(4).toInstant(),snapshot.version(),mode),snapshot.cart(),snapshot.version(),snapshot.addressHash(),snapshot.packageHash(),service,mode,java.sql.Timestamp.from(clock.instant()));return rows.isEmpty()?null:rows.getFirst();}
 private Snapshot checkedSnapshot(ActorAssertion.Actor actor,UUID cart,long expected,DeliveryQuoteValues.Input input,boolean lock){try{return snapshot(actor,cart,expected,input,lock);}catch(Problem.Failure failure){if(failure.code==ProblemCode.PRICING_RULE_VIOLATION)throw FulfillmentValues.rule();throw failure;}}
 public DeliveryQuoteValues.Quote create(ActorAssertion.Actor actor,String session,UUID cart,long expected,DeliveryQuoteValues.Input input,String key,UUID correlation){
  authority.require(actor,"CUSTOMER");if(cart==null||cart.equals(new UUID(0,0))||expected<0||expected==Long.MAX_VALUE||session==null||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();ApiValues.idempotencyKey(key);
  var commandInput=EventCodec.JSON.valueToTree(Map.of("cart",cart,"version",expected,"body",input));
  var owned=jdbc.queryForList("SELECT organization_id FROM commerce.cart WHERE id=? AND party_id=?",cart,actor.party());if(owned.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);UUID currentOrganization=(UUID)owned.getFirst().get("organization_id");if(currentOrganization!=null)authority.organization(actor,currentOrganization,false);
  if(commands.completed(actor.party().toString(),"API-181",key)){fulfillment.require(mode,"FEDEX");providers.require(mode);var replay=commands.executeLocal(actor.party().toString(),"API-181",key,commandInput,db->{throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);});var saved=EventCodec.JSON.treeToValue(replay.body(),DeliveryQuoteValues.Quote.class);if(!mode.equals(saved.mode()))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);authority.require(actor,"CUSTOMER");return saved;}
  var captured=snapshots.execute(s->checkedSnapshot(actor,cart,expected,input,false));UUID command=UUID.nameUUIDFromBytes(("API-181:"+actor.party()+":"+key).getBytes(StandardCharsets.UTF_8));var request=new CarrierRates.Request(command,cart,"NG","NGN",origin,captured.address(),captured.packages(),input.serviceCode());
  var binding=new ActorAssertion.Binding("integration",HttpCarrierRates.ROUTE.scope(),"POST",HttpCarrierRates.ROUTE.path(),correlation,ActorAssertion.Binding.bodyHash(HttpCarrierRates.body(request)));String assertion=captured.organization()==null?delegation.issue(session,binding,null):delegation.issue(session,binding,captured.organization(),authority.entitlement());var rate=rates.quote(request,assertion,correlation);authority.require(actor,"CUSTOMER");
  if(!rate.provider().equals("FEDEX")||!rate.currency().equals("NGN")||!rate.serviceCode().matches("[A-Z][A-Z0-9_]{0,79}")||input.serviceCode()!=null&&!input.serviceCode().equals(rate.serviceCode())||!rate.amount().matches("[0-9]{1,15}\\.[0-9]{2}")||!rate.expiresAt().isAfter(clock.instant())||rate.expiresAt().isAfter(clock.instant().plusSeconds(300)))throw FulfillmentValues.rule();
  var response=commands.executeLocal(actor.party().toString(),"API-181",key,commandInput,db->{
   var current=checkedSnapshot(actor,cart,expected,input,true);if(!current.addressHash().equals(captured.addressHash())||!current.packageHash().equals(captured.packageHash())||!Objects.equals(current.organization(),captured.organization())||!current.market().equals(captured.market()))throw new Problem.Failure(ProblemCode.CHECKOUT_REPRICE_REQUIRED);if(!rate.expiresAt().isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);var previous=existing(current,rate.serviceCode(),true);if(previous!=null)return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(previous),previous.id());
   Instant expires=rate.expiresAt().isBefore(current.approvalUntil())?rate.expiresAt():current.approvalUntil();expires=expires.truncatedTo(java.time.temporal.ChronoUnit.MICROS);if(!expires.isAfter(clock.instant()))throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);UUID id=EventCodec.uuid7(clock.instant());String actorId=actor.party().toString();var providerSnapshot=EventCodec.JSON.valueToTree(Map.of("rate",rate,"shipper",origin));
   var saved=jdbc.queryForList("INSERT INTO commerce.carrier_quote(id,created_by,updated_by,cart_id,cart_version,market_id,provider,mode,provider_quote_reference,service_code,currency_code,delivery_amount,address_hash,package_hash,package_snapshot,provider_snapshot,expires_at,status) VALUES (?,?,?,?,?,?,'FEDEX',?,?,?,'NGN',?,?,?,?::jsonb,?::jsonb,?,'QUOTED') ON CONFLICT(cart_id,cart_version,address_hash,package_hash,service_code,mode) DO UPDATE SET provider_quote_reference=excluded.provider_quote_reference,delivery_amount=excluded.delivery_amount,provider_snapshot=excluded.provider_snapshot,expires_at=excluded.expires_at,status='QUOTED',version=commerce.carrier_quote.version+1,updated_at=now(),updated_by=excluded.updated_by WHERE commerce.carrier_quote.status IN ('QUOTED','EXPIRED') AND commerce.carrier_quote.source_quote_revision_id IS NULL AND commerce.carrier_quote.version<9223372036854775807 RETURNING id",id,actorId,actorId,cart,expected,current.market(),mode,rate.providerReference(),rate.serviceCode(),new BigDecimal(rate.amount()),current.addressHash(),current.packageHash(),EventCodec.JSON.writeValueAsString(current.packages()),EventCodec.JSON.writeValueAsString(providerSnapshot),java.sql.Timestamp.from(expires));if(saved.size()!=1)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);id=(UUID)saved.getFirst().get("id");var after=new DeliveryQuoteValues.Quote(id,"FEDEX",rate.serviceCode(),"NGN",rate.amount(),expires,expected,mode);audit.append(actorId,AuditValues.ActorKind.USER,AuditValues.Action.CHECKOUT_QUOTE,AuditValues.Resource.QUOTE,id,correlation,AuditValues.Reason.VERIFIED_PROVIDER,null,Map.of("amount",rate.amount(),"currency","NGN","version",expected),null);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(after),id);
  });authority.require(actor,"CUSTOMER");return EventCodec.JSON.treeToValue(response.body(),DeliveryQuoteValues.Quote.class);
 }
}
